// MODULE 9's ORIGINAL MANUAL VERIFICATION (a one-time, human-performed check):
// "Directly inspect a newly created user's stored password field via a
// database client tool, confirming it's a bcrypt-formatted string, not
// anything resembling the original plaintext password."
// - requires a human to remember to do this, every single time, manually

// THIS LESSON's AUTOMATED EQUIVALENT - written once, runs forever,
// automatically, on every single future change:
import bcrypt from 'bcrypt';

describe('password hashing', () => {
  it('never stores the plaintext password', async () => {
    const plainPassword = 'mySecurePassword123';
    const hashedPassword = await bcrypt.hash(plainPassword, 10);

    expect(hashedPassword).not.toBe(plainPassword);
    expect(hashedPassword).not.toContain(plainPassword);
  });

  it('correctly verifies a matching password', async () => {
    const plainPassword = 'mySecurePassword123';
    const hashedPassword = await bcrypt.hash(plainPassword, 10);

    const isMatch = await bcrypt.compare(plainPassword, hashedPassword);
    expect(isMatch).toBe(true);
  });

  it('correctly rejects a non-matching password', async () => {
    const hashedPassword = await bcrypt.hash('correctPassword', 10);
    const isMatch = await bcrypt.compare('wrongPassword', hashedPassword);
    expect(isMatch).toBe(false);
  });
});

