function calculateOrderTotal(items: { price: number; quantity: number }[], couponCode?: string): number {
  let total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
  if (couponCode === 'SAVE10') total *= 0.9;
  return total;
}

describe('calculateOrderTotal', () => {
  it('correctly sums item prices times quantities', () => {
    const total = calculateOrderTotal([{ price: 10, quantity: 2 }, { price: 5, quantity: 1 }]);
    expect(total).toBe(25);
  });

  it('applies a 10% discount with a valid coupon code', () => {
    const total = calculateOrderTotal([{ price: 100, quantity: 1 }], 'SAVE10');
    expect(total).toBe(90);
  });

  it('does not apply a discount with an invalid coupon code', () => {
    const total = calculateOrderTotal([{ price: 100, quantity: 1 }], 'INVALID');
    expect(total).toBe(100);
  });
});

