import { checkStock } from '../models/inventoryModel';
import { createOrder } from '../models/orderModel';
import { processCheckout, InsufficientStockError } from '../services/orderService';

describe('processCheckout', () => {
  beforeEach(() => {
    jest.clearAllMocks(); // reset mocks between tests, so one test's
                            // mock configuration never leaks into another
  });

  it('successfully creates an order when stock is sufficient', async () => {
    (checkStock as jest.Mock).mockResolvedValue(true);
    (createOrder as jest.Mock).mockResolvedValue({ id: 'order123', total: 50 });

    const result = await processCheckout([{ productId: 'p1', quantity: 2, price: 25 }]);

    expect(result.id).toBe('order123');
    expect(checkStock).toHaveBeenCalledWith('p1', 2); // verifying HOW
      // the mock was called, not just what it returned
  });

  it('throws InsufficientStockError and never creates an order when stock is insufficient', async () => {
    (checkStock as jest.Mock).mockResolvedValue(false);

    await expect(processCheckout([{ productId: 'p1', quantity: 100, price: 25 }]))
      .rejects.toThrow(InsufficientStockError);

    expect(createOrder).not.toHaveBeenCalled(); // verifying the ORDER
      // creation step never even ran, exactly the all-or-nothing
      // behavior Module 19 lesson 4's transactions guaranteed at the
      // database level, now verified at the Service-logic level
  });
});

