  await page.click('button:has-text("Buy Now")');
  await expect(page.locator('text=Order confirmed')).toBeVisible();

  // Navigate back and verify inventory genuinely decremented - this
  // is the SAME real database Module 19 lesson 4's transaction wrote
  // to, verified here through the actual UI a real user would see
  await page.goto('http://localhost:3000/products/widget-123');
  const stockAfter = await page.locator('[data-testid="stock-count"]').textContent();

  expect(Number(stockAfter)).toBe(Number(stockBefore) - 1);
});

